const DEMO = true; // set false for live quiet hours
const OPEN = 7;
const CLOSE = 21;
const now = new Date();
if (DEMO) {
  return [{ json: { ...$input.first().json, sendWindow: 'DEMO (no hold)', holdUntilWindow: false, waitMinutes: 0, sendAt: now.toISOString(), demo: true } }];
}
const parts = Object.fromEntries(new Intl.DateTimeFormat("en-GB", { timeZone: "Africa/Nairobi", hour: "numeric", minute: "numeric", hourCycle: "h23" })
    .formatToParts(now)
    .map((part) => [part.type, part.value]));
const hour = Number(parts.hour) + Number(parts.minute) / 60;
let waitMinutes = 0;
if (hour < OPEN)
    waitMinutes = Math.ceil((OPEN - hour) * 60);
else if (hour >= CLOSE)
    waitMinutes = Math.ceil((24 - hour + OPEN) * 60);
return [
    {
        json: {
            ...$input.first().json,
            sendWindow: `${OPEN}:00–${CLOSE}:00 Nairobi`,
            holdUntilWindow: waitMinutes > 0,
            waitMinutes,
            sendAt: new Date(now.getTime() + waitMinutes * 60_000).toISOString(),
            demo: false,
        },
    },
];

const failed = $("Payment failed (RabbitMQ)").first().json;
const info = $("Order & viewer (storefront)").first().json;
const link = $("Resume link (storefront)").first().json;
const rabbit = failed;
const rabbitPhone = rabbit.properties?.phone || rabbit.phone || '';
const rabbitEmail = rabbit.properties?.email || rabbit.email || '';
const reason = failed.properties.reason ?? "declined";
const strategies = {
    insufficient_funds: "Top up M-Pesa and you’re done — we held the film for you.",
    wrong_pin: "The PIN didn’t match. Try again; it only takes a few seconds.",
    timeout_or_cancel: "The M-Pesa prompt timed out. Try again when your phone is ready.",
    limit_exceeded: "That went over your M-Pesa limit — pay by card or Till instead.",
    declined: "The payment was declined. Try again or use another way to pay.",
};
const first = (info.user && info.user.firstName) || 'there';
const films = Array.isArray(link.films) ? link.films : [];
const title = films.map((film) => film.title).join(" + ") || (info.order && info.order.movieTitle) || 'your film';
const poster = (films[0] && (films[0].poster || films[0].posterUrl || films[0].image)) || '';
const fallbacks = {
    insufficient_funds: `Pole ${first} — M-Pesa balance was short for ${title} (KES ${link.totalKes}). Top up & tap to finish (we saved it):`,
    wrong_pin: `Pole ${first} — M-Pesa PIN didn’t go through for ${title}. Tap to try again:`,
    timeout_or_cancel: `Pole ${first} — M-Pesa prompt for ${title} timed out. Tap when ready:`,
    limit_exceeded: `Pole ${first} — ${title} went over your M-Pesa limit. Tap to pay by card/Till:`,
};
return [{
  json: {
    userId: info.user.id,
    orderId: info.order.id,
    phone: (info.user && info.user.phone) || rabbitPhone,
    email: (info.user && info.user.email) || rabbitEmail || '',
    channelPref: info.user.channelPref || info.user.channel_pref || 'both',
    name: (info.user && info.user.name) || first,
    subject: `Pole ${first} — let’s finish ${title}`,
    scenario: 'B_rescue',
    firstName: first,
    title,
    filmTitle: title,
    reason,
    strategy: strategies[reason] ?? strategies.declined,
    reasonHint: strategies[reason] ?? strategies.declined,
    totalKes: link.totalKes,
    priceKes: link.totalKes,
    url: link.url,
    ctaUrl: link.url,
    ctaLabel: 'Complete payment',
    imageUrl: poster,
    films,
    nudgeId: link.nudgeId,
    movieIds: films.map((film) => film.id),
    discountPct: link.discountPct,
    alternative: reason === "limit_exceeded" ? "" : " Or pay by card.",
    fallback: fallbacks[reason] ?? `Pole ${first} — payment for ${title} didn’t go through. Tap to try again:`,
  },
}];

const facts = $("Rescue facts").first().json;
const ai = $input.first().json ?? {};
const text = String(ai.output?.message ?? ai.text ?? "").trim();
let fallbackReason = null;
if (!text)
    fallbackReason = ai.error ? "AI error" : "no AI answer";
else if (text.length > 120)
    fallbackReason = "too long";
else if (/https?:|www\.|\.com|\.app/i.test(text))
    fallbackReason = "contains a link";
else {
    const prices = [...text.matchAll(/KES\s?([\d,]+)/gi)].map((match) => Number(match[1].replace(/,/g, "")));
    if (prices.some((price) => price !== facts.totalKes))
        fallbackReason = "wrong price";
}
const body = fallbackReason ? facts.fallback : text;
return [{ json: { ...facts, message: `${body} ${facts.url}${facts.alternative}`.trim(), aiUsed: !fallbackReason, fallbackReason } }];

let message = '';
try {
  const raw = $input.first().json || {};
  const content = raw.choices?.[0]?.message?.content || raw.message || '';
  if (typeof content === 'string' && content.trim().startsWith('{')) {
    const parsed = JSON.parse(content);
    message = String(parsed.message || parsed.text || '').trim();
  } else {
    message = String(content || '').trim();
  }
} catch (e) { message = ''; }
return [{ json: { output: { message }, text: message } }];
